def oof(X,lams):
    out={}; Ks=[]
    for f in range(5):
        tr=folds!=f; te=~tr
        mu=X[tr].mean(0); sd=X[tr].std(0)+1e-6; Z=(X[tr]-mu)/sd; Ze=(X[te]-mu)/sd
        Ks.append((Z@Z.T, Ze@Z.T, tr, te))
    for lam in lams:
        o=np.zeros((N,8))
        for K,Ke,tr,te in Ks:
            al=np.linalg.solve(K+lam*np.eye(len(K)),Y[tr]-Y[tr].mean(0)); o[te]=Ke@al
        out[lam]=round((o.argmax(1)==lab).mean(),4)
    return out
